import ast
DANGEROUS = {'eval', 'exec', 'open', 'subprocess', 'socket', 'os.system'}
def scan_code(src):
    hits = set()
    try: tree = ast.parse(src)
    except SyntaxError: return {'unparseable'}
    for node in ast.walk(tree):
        if isinstance(node, ast.Name) and node.id in DANGEROUS: hits.add(node.id)
    return hits
